  display: -moz-box;
  display: -ms-flexbox;
  display: -webkit-flex;
  display: flex;
}

.flexCenter {
  -webkit-align-content: center;
  -webkit-justify-content: center;
  align-content: center;
  justify-content: center;
}

/* remove for equal height cols */
.flexCenterItems {
  align-items: center;
}

.flexFlexEnd {
  justify-content: flex-end;
}

.flexTopItems {
  align-items: flex-start;
}

.rowWrap {
  flex-flow: row wrap;
  -webkit-flex-flow: row wrap;
}

.flexColumnStack {
  flex-direction: column;
  margin: 0 auto;
}

.flexInner {}

.flexVerticalCenter {
  display: flex;
  flex-direction: column;
  justify-content: center;
}


