#progress {
  position: relative;
  margin-bottom: 30px;
}

#progress-bar {
  position: absolute;
  background: var(--primary);
  height: 5px;
  width: 0%;
  top: 50%;
  left: 0;
}

#progress-num {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  justify-content: space-between;
}

#progress-num::before {
  content: "";
  background-color: lightgray;
  position: absolute;
  top: 50%;
  height: 2px;
  width: 100%;
  z-index: 1;
}

#progress-num .step {
  border: 2px solid lightgray;
  border-radius: 100%;
  width: 40px;
  height: 40px;
  line-height: 34px;
  text-align: center;
  background-color: var(--light);
  font-size: 1rem;
  position: relative;
  z-index: 1;
}

#progress-num .active {
